"""Generates src/locale/us-hcup-ccsr.ts from docs/us-hcup-ccsr-2022-2023.csv (HCUPnet export, 2023 rows).
Usage: python -I -X utf8 scripts/us-hcup-ccsr-build.py   (run from the repo root)"""
import csv

rows = [r for r in csv.DictReader(open("docs/us-hcup-ccsr-2022-2023.csv", encoding="utf-8")) if r["year"] == "2023"]


def num(s):
    return "null" if s == "" else repr(round(float(s), 2)) if "." in s else s


out = [
    "/**",
    " * HCUP National Inpatient Sample 2023, principal diagnosis by CCSR category (Epic X M10.5c step E).",
    " * GENERATED by scripts/us-hcup-ccsr-build.py from docs/us-hcup-ccsr-2022-2023.csv; do not edit by hand.",
    " * Source: HCUPnet (AHRQ), weighted national estimates, all stays; docs/us-calibration-targets.md T-LOS-2.",
    " * los = mean length of stay in days; deathPct = percent of discharges who died in hospital.",
    " * null = suppressed by HCUPnet (fewer than 11 discharges or deaths, or relative standard error over 0.30).",
    " */",
    "export interface CcsrStats { name: string; discharges: number | null; los: number | null; deathPct: number | null; }",
    "",
    "export const US_HCUP_CCSR_2023: Readonly<Record<string, CcsrStats>> = {",
]
for r in sorted(rows, key=lambda r: r["ccsr"]):
    code, name = r["ccsr"].split(":", 1)
    name = name.strip().replace("\\", "\\\\").replace('"', '\\"')
    d = r["discharges"]
    out.append(f'  {code}: {{ name: "{name}", discharges: {num(d)}, los: {num(r["mean_los_days"])}, deathPct: {num(r["death_pct"])} }},')
out.append("};")
out.append("")
open("src/locale/us-hcup-ccsr.ts", "w", encoding="utf-8", newline="\n").write("\n".join(out))
print(len(rows), "categories")
